import { USERS, expect, test } from "../../fixtures";

test.describe("Sign in", () => {
  test("Current user is returned for a valid session", { tag: "@AUTH-04" }, async ({ apiAs }) => {
    // Given I am signed in as member@northwind.test
    const member = await apiAs("member");

    // When I request my profile
    const response = await member.get("/api/me");

    // Then the response status is 200
    expect(response.status(), await response.text()).toBe(200);

    // And the profile shows role "member" and tenant "Northwind Supply"
    const profile = await response.json();
    expect(profile.email).toBe(USERS.member);
    expect(profile.role).toBe("member");
    expect(profile.tenant.name).toBe("Northwind Supply");
  });
});
